<script setup lang="ts">import {computed,ref} from 'vue';import {useQuery} from '@tanstack/vue-query';import {productRepository} from '../../services/productRepository';import DetailDrawer from '../../components/common/DetailDrawer.vue';import StatusTag from '../../components/common/StatusTag.vue';const keyword=ref('');const selected=ref<Record<string,unknown>|null>(null);const query=useQuery({queryKey:['product-lines'],queryFn:()=>productRepository.productLines(keyword.value)});const refresh=()=>{void query.refetch()};const rows=computed(()=>{const items=query.data.value||[];const key=keyword.value.trim().toLowerCase();return key?items.filter(item=>Object.values(item).some(value=>String(value??'').toLowerCase().includes(key))):items});const cell=(row:Record<string,unknown>,index:number)=>[row.name,row.code,row.ownerName,row.status,row.updatedAt][index]??'—';</script>
<template><section class="crm-view"><div class="section-heading"><div><span class="eyebrow">PRODUCT LINES</span><h2>产品线</h2></div><button class="secondary" @click="refresh">刷新</button></div><div class="toolbar"><input v-model="keyword" placeholder="搜索产品线" @keyup.enter="refresh"/><span>{{rows.length}} 条记录</span></div><div v-if="query.isPending" class="state">正在加载产品线…</div><div v-else-if="query.isError" class="state error">产品线加载失败。</div><div v-else-if="!rows.length" class="state">暂无产品线。</div><div v-else class="table-wrap"><table><thead><tr><th>产品线名称</th><th>编码</th><th>负责人</th><th>状态</th><th>更新时间</th></tr></thead><tbody><tr v-for="row in rows" :key="String(row.id)" @click="selected=row"><td>{{cell(row,0)}}</td><td>{{cell(row,1)}}</td><td>{{cell(row,2)}}</td><td><StatusTag :status="cell(row,3)" /></td><td>{{cell(row,4)}}</td></tr></tbody></table></div><DetailDrawer :open="Boolean(selected)" title="产品线详情" @close="selected=null"><dl v-if="selected" class="detail-list"><template v-for="(value,key) in selected" :key="key"><dt>{{key}}</dt><dd>{{String(value??'—')}}</dd></template></dl></DetailDrawer></section></template>
